import { calculations, choices, part, table } from './science-practice-tools.js';

function topic(number, simple, challenge, numeric = []) {
  const bank = 'biology-' + number;
  return [
    ...choices(bank, 'simple', simple),
    ...choices(bank, 'challenge', challenge),
    ...calculations(bank, numeric),
  ];
}

function diagram(caption, alt, height, content) {
  return {
    caption, alt,
    svg: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 ${height}" aria-hidden="true">
      <g font-family="system-ui, sans-serif" font-size="15" fill="#24433b">${content}</g>
    </svg>`,
  };
}

